/* 双首页：共用视觉与创作承接，官网展示作品，工作空间优先续作。 */
(()=>{
  const C=Cimora,{S,M,E,link,art,path}=C;
  const H={slide:0,step:0,engineering:'ready',collection:'all'};
  const films=[
    {title:'星海邮局',en:'LETTERS TO THE STARS',tag:'奇幻 · 原创世界',type:'漫画',cover:'assets/cimora-cover.webp',id:'sky-public',line:'替星星寄信的人，也在寻找自己的归处。',prompt:'星海邮局的女孩收到一封未来的来信，她必须在日落前找到寄信的人。',position:'center 30%'},
    {title:'雨停之前',en:'BEFORE THE RAIN ENDS',tag:'都市 · 温柔重逢',type:'漫画 / 视频',cover:'assets/cimora-story-4.webp',id:'rain-public',line:'一封没有寄出的信，一场迟到七年的重逢。',prompt:'女孩重返阔别七年的书店，遇见一直替她保存着一封信的人。',position:'center 42%'},
    {title:'夏日的末班车',en:'THE LAST TRAIN OF SUMMER',tag:'青春 · 音乐之旅',type:'视频概念',cover:'assets/cimora-sunset.webp',id:null,line:'在夏天结束之前，再勇敢出发一次。',prompt:'背着吉他的女孩赶上夏日末班车，去完成一场没有观众的海边演出。',position:'center 48%'}
  ];
  const stages={story:'故事与章节',boards:'分镜与草图',assets:'资产与约束',comic:'漫画排版',motion:'音画视频',audio:'剪辑与声音',review:'审查与交付'};
  const action=(text,key,cls='hm-button',extra='')=>`<button type="button" class="${cls}" data-home="${key}" ${extra}>${text}</button>`;
  const label=(no,title,desc='',tail='')=>`<div class="hm-section-heading"><div><span class="hm-eyebrow">${no}</span><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${tail}</div>`;
  function inputState(scope){M.db.homeInputs??={};return M.db.homeInputs[scope]??={text:'',mode:'comic'};}
  function composer(scope){const d=inputState(scope);return `<form class="hm-composer ${scope}" data-home-form="start" data-scope="${scope}"><div class="hm-composer-modes" aria-label="选择创作方式">${[['comic','▤','漫画'],['motion','▷','视频'],['canvas','⌘','自由画布']].map(([k,ic,t])=>action(`<span>${ic}</span>${t}`,'mode','',`data-mode="${k}" aria-pressed="${d.mode===k}"`)).join('')}<span class="hm-composer-hint">先写一句，就能开始</span></div><label class="hm-sr" for="hm-idea-${scope}">写下你的故事灵感</label><textarea id="hm-idea-${scope}" name="idea" rows="2" maxlength="6000" placeholder="例如：一个替星星寄信的女孩，收到了未来自己的来信……" data-home-input="idea">${E(d.text)}</textarea><div class="hm-composer-bottom">${action('✧ 换个灵感','sample','hm-subtle')}${action('草稿箱'+(M.db.draftBackups?.length?' · '+M.db.draftBackups.length:''),'drafts','hm-subtle')}<button class="hm-button primary" type="submit">开始构思 <span>↗</span></button></div></form>`;}
  function slides(){return films.map((f,i)=>{const offset=(i-H.slide+3)%3,place=offset===0?'current':offset===1?'next':'previous';return `<article class="hm-film ${place}" aria-hidden="${place!=='current'}"><img src="${f.cover}" alt="${place==='current'?f.title+' · 二次元原创画面':''}" style="object-position:${f.position}" ${i?'loading="lazy"':'fetchpriority="high"'}><div class="hm-film-shade"></div><div class="hm-film-caption"><span class="hm-film-tag">${f.tag} <i></i> ${f.type}</span><h2>${f.title}</h2><p>${f.line}</p><div>${action('查看作品画面 ↗','preview','hm-button glass',`data-film="${i}" tabindex="${place==='current'?0:-1}"`)}<small>原创概念画面 · 静态预览</small></div></div><span class="hm-film-edition">${f.en} <b>0${i+1} / 03</b></span></article>`;}).join('');}
  function gallery(){return `<section class="hm-gallery" aria-label="Cimora 精选作品轮播" tabindex="0"><div class="hm-gallery-intro"><span class="hm-eyebrow">CIMORA · A HOME FOR YOUR IMAGINATION</span><h1>让喜欢的世界，<em>成为你的作品。</em></h1><p>从一句灵感，到一章漫画，再到会动的故事。</p></div><div class="hm-film-stage"><div id="hm-slides">${slides()}</div>${action('←','previous','hm-carousel-arrow left','aria-label="上一部作品"')}${action('→','next','hm-carousel-arrow right','aria-label="下一部作品"')}</div><div class="hm-carousel-bottom"><span id="hm-film-announcement" aria-live="polite">01 — ${films[H.slide].title}</span><div aria-label="选择精选作品">${films.map((f,i)=>action(`<span class="hm-sr">${f.title}</span>`,'slide','hm-dot',`data-index="${i}" aria-label="切换到${f.title}" aria-pressed="${H.slide===i}"`)).join('')}</div><span>你的故事，下一个登场。</span></div></section>`;}
  const capabilities=[
    ['漫画创作','让故事，一格格展开。','comic',0,'▤'],['视频创作','给画面一点生命力。','motion',4,'▷'],['OC 角色档案','让每一次登场都熟悉。','oc',1,'◎'],['无限画布','灵感自由，关系清楚。','canvas',3,'⌘'],['创作小工具','从一个小想法开始。','tools',8,'✧']
  ];
  function capabilitiesSection(){return `<section class="hm-capabilities" aria-label="创作能力">${capabilities.map(([t,d,k,n,ic])=>link(`<div class="hm-capability-art ${k}">${k==='canvas'?`<span class="hm-tiny-graph"><i>故事</i><b>→</b><i>角色</i><b>→</b><i>分镜</i></span>`:art(n,t)}<span>${ic}</span></div><div><h3>${t}<b>↗</b></h3><p>${d}</p></div>`,k==='oc'?'/app/tools/oc-sheet':k==='tools'?'/app/tools':k==='canvas'?'/app/new?view=canvas':'/app/new?output='+k,'hm-capability')).join('')}</section>`;}
  const process=[
    {title:'先把故事，讲好。',desc:'一句想法也可以开始。一起扩写情节、打磨对白，拆成可继续制作的章节。',cta:'从一个想法开始',url:'/app/new',kind:'story'},
    {title:'让文字，长成分镜。',desc:'先确认叙事与动作，再生成草图。每一格的对白、顺序和细节，都留给你修改。',cta:'了解漫画创作',url:'/features/webtoon',kind:'boards'},
    {title:'让角色，始终是他。',desc:'角色、场景、道具归属项目与章节。固定引用版本，持续创作时有迹可循。',cta:'看看角色档案',url:'/app/tools/oc-sheet',kind:'assets'},
    {title:'同一个故事，多一种表达。',desc:'漫画直接排版，视频继续安排镜头与声音。流程与无限画布之间，自由切换。',cta:'从视频开始',url:'/app/new?output=motion',kind:'motion'}
  ];
  function processPreview(){const k=process[H.step].kind;return `<div class="hm-preview-bar"><span><i></i> 雨停之前 / 创作示例</span><span>${['STORY ROOM','STORYBOARDS','WORLD BIBLE','MOTION STUDIO'][H.step]}</span></div>${k==='story'?`<div class="hm-script-preview"><span>CHAPTER 01</span><h3>雨中的重逢</h3><p>七年后，林夏回到街角的旧书店。<br>门铃响起，熟悉的身影从书架后转身。</p><blockquote>“我以为，你不会再来了。”</blockquote><div><span>原始想法</span><b>→</b><span>故事大纲</span><b>→</b><span class="active">章节内容</span></div><small>候选可编辑 · 原文独立保留</small></div>`:k==='boards'?`<div class="hm-boards-preview">${[0,1,3].map((n,i)=>`<figure>${art(n)}<figcaption><span>0${i+1}</span>${['旧书店 · 远景','重逢目光 · 特写','未寄出的信 · 近景'][i]}</figcaption></figure>`).join('')}</div><div class="hm-preview-foot"><span>草图 v2</span><span>对白与阅读顺序，一起保存</span></div>`:k==='assets'?`<div class="hm-assets-preview"><div class="hm-character">${art(1)}<span>林夏 <b>v2 · 已锁定</b></span></div><div><span class="hm-eyebrow">本章固定引用</span>${[[0,'旧书店','场景 v1'],[3,'未寄出的信','道具 v1'],[2,'陈序','角色 v1']].map(([n,t,v])=>`<div class="hm-asset-mini">${art(n)}<div><strong>${t}</strong><small>${v}</small></div><span>✓</span></div>`).join('')}<p>新版本由你确认，已有画面继续保留。</p></div></div>`:`<div class="hm-motion-demo">${art(4)}<span class="hm-preview-subtitle">“这一次，一起走吧。”</span><span class="hm-motion-tag">稳定运镜 · CSS 示意</span></div><div class="hm-demo-timeline">${[0,1,2,3,4,8].map((n,i)=>`<span>${art(n)}<b>0${i+1}</b></span>`).join('')}</div>`}`;}
  function processSection(){return `<section class="hm-section hm-process" id="hm-process">${label('01 / MAKE YOUR STORY','创作的每一步，<br>都在你的掌握之中。','从第一句故事，到第一部作品。')}<div class="hm-process-grid"><div class="hm-process-steps">${process.map((x,i)=>`<article class="${H.step===i?'active':''}"><h3>${action(`<span>0${i+1}</span>${x.title}<b>↗</b>`,'process','',`data-index="${i}" aria-expanded="${H.step===i}" aria-controls="hm-process-preview"`)}</h3><div class="hm-process-copy" ${H.step!==i?'hidden':''}><p>${x.desc}</p>${link(x.cta+' →',x.url,'hm-text-link')}</div></article>`).join('')}</div><div id="hm-process-preview" class="hm-process-preview" role="region" aria-label="制作步骤预览" aria-live="polite">${processPreview()}</div></div></section>`;}
  function engineeringPreview(){const state=H.engineering,changed=state==='changed',failed=state==='failed',recovered=state==='recovered';return `<div class="hm-graph-header"><span><i></i> 雨停之前 / 第 01 章</span><span class="hm-sample-tag">独立示例工程</span></div><div class="hm-engine-nodes">${[['角色资产',changed?'v2 · 新版本':'v1 · 固定引用','asset'],['分镜草图',changed?'需要复核':'已完成','boards'],['漫画排版',changed?'来源已更新':'稳定版保留','layout'],['动态镜头',failed?'生成失败':recovered?'恢复完成':changed?'来源已更新':'稳定底稿','motion']].map(([t,v,k],i)=>`<div class="hm-engine-node ${changed&&i>0?'stale':failed&&i===3?'failed':recovered&&i===3?'recovered':''}"><span>${['◎','▤','▥','▷'][i]}</span><strong>${t}</strong><small>${v}</small></div>${i<3?'<b class="hm-engine-arrow">→</b>':''}`).join('')}</div><div class="hm-engine-status" role="status"><span class="hm-pulse"></span><div><strong>${changed?'3 个下游步骤需要复核':failed?'视频步骤超时，成功结果保留':recovered?'只恢复动态步骤，其他结果未重做':'一个工程，管理故事的每次生长。'}</strong><p>${changed?'旧采用版本与画面继续保留，由你决定何时同步。':failed?'漫画排版与稳定底稿仍可用，可以单独恢复失败步骤。':recovered?'示例恢复完成；没有调用模型，不产生真实费用。':'角色、章节、候选与交付之间的关系清晰可见。'}</p></div>${state!=='ready'?action('重置','engineering','hm-subtle','data-state="ready"'):''}</div>`;}
  function engineeringSection(){return `<section class="hm-section hm-engineering">${label('02 / BUILT FOR KEEPING GOING','好创作，需要能继续的工程。','可以接不同的模型 API，也要管好输入、版本与每一次重试。')}<div class="hm-engineering-grid"><div><div class="hm-engine-choice">${action('◎ 试试资产版本更新','engineering','hm-button secondary','data-state="changed"')}${action('↶ 试试失败恢复','engineering','hm-button secondary','data-state="failed"')}${action('只恢复失败步骤 →','recover','hm-button primary')}</div><p class="hm-engine-explainer">改一处，知道影响哪里。<br>失败一步，继续已经做好的部分。</p>${link('进入我的创作空间 ↗','/app','hm-text-link')}<small>交互示例独立于你的项目，不修改真实工程。</small></div><div class="hm-engine-preview" id="hm-engine-preview">${engineeringPreview()}</div></div></section>`;}
  function workTile(f,i){return `<article class="hm-work-tile">${action(`<img src="${f.cover}" alt="${f.title}" loading="lazy" style="object-position:${f.position}"><span class="hm-work-kind">${f.type}</span><span class="hm-preview-icon">↗</span>`,'preview','hm-work-art',`data-film="${i}" aria-label="预览${f.title}"`)}<div><h3>${f.title}</h3><p>${f.tag}<span>原创演示</span></p></div></article>`;}
  function storyTile(){return `<article class="hm-work-tile">${action('<img src="assets/cimora-cover.webp" alt="末班车录音故事示例"><span class="hm-work-kind">故事</span><span class="hm-preview-icon">阅读全文 ↗</span>','read-story','hm-work-art','aria-label="阅读完整故事：末班车录音"')}<div><h3>末班车录音</h3><p>悬疑 · 迟来的和解<span>原创完整短篇</span></p></div></article>`;}
  function collection(){const shown=films.map((f,i)=>({f,i})).filter(({i})=>H.collection==='all'||H.collection==='comic'&&i<2||H.collection==='motion'&&i>0);return (['all','story'].includes(H.collection)?storyTile():'')+shown.map(({f,i})=>workTile(f,i)).join('');}
  function worksSection(app=false){return `<section class="${app?'hm-workspace-section':'hm-section'}">${label(app?'发现灵感':'03 / MADE OF IMAGINATION',app?'从别人的世界，找到你的灵感。':'每一个故事，都有自己的光。','',link('探索作品广场 ↗','/app/community','hm-text-link'))}<div class="hm-collection-filters" aria-label="作品筛选">${[['all','精选作品'],['story','故事'],['comic','漫画'],['motion','视频']].map(([k,t])=>action(t,'collection','',`data-filter="${k}" aria-pressed="${H.collection===k}"`)).join('')}</div><div class="hm-work-grid" id="hm-collection">${collection()}</div></section>`;}
  function templatesSection(app=false){return `<section class="${app?'hm-workspace-section':'hm-section'}">${label(app?'设定与资产':'04 / WORLDS TO CREATE WITH','让好设定，成为新作品的起点。','',link('进入创作市场 ↗','/app/market','hm-text-link'))}<div class="hm-template-grid">${C.catalog().filter(x=>['urban-character','night-city','star-post'].includes(x.id)).map(x=>`<article class="hm-template-card"><a class="hm-template-art" href="#/app/market/${x.id}"><img src="${E(x.cover)}" alt="${E(x.title)}" loading="lazy"><span>${E(x.category)}</span><b>预览资产包 ↗</b></a><div><small>${E(x.category)} / ${E(x.author)}</small><h3>${E(x.title)}</h3><p>${E(x.desc)}</p><footer><span>${x.price.toLocaleString('zh-CN')} 积分 · 示例</span>${link('查看交付 →','/app/market/'+x.id,'hm-text-link')}</footer></div></article>`).join('')}</div></section>`;}
  function official(){S.pageTitle='让喜欢的世界，成为你的作品';return `<main class="hm-home hm-official">${gallery()}<div class="hm-public-launch">${composer('public')}</div><div class="hm-main-width">${capabilitiesSection()}${processSection()}${engineeringSection()}${worksSection()}${templatesSection()}<section class="hm-final-cta"><span class="hm-eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>下一部喜欢的作品，<br>由你开始。</h2>${link('进入创作空间 ↗','/app','hm-button primary large')}<p>故事共创 · 统一资产 · 自由画布 · 动态演绎</p></section></div></main>`;}
  function projectContexts(){return S.state.projects.filter(p=>!p.archived).map(p=>M.resume(p)).sort((a,b)=>(b.p.lastOpenedAt||'').localeCompare(a.p.lastOpenedAt||''));}
  function projectCard(c){const {p,e}=c,url=M.navigation?.resume(c)||path(c,e.stage,e.view),failed=e.graph.nodes.filter(n=>n.status==='failed').length,stale=e.graph.nodes.filter(n=>n.status==='stale').length,done=e.graph.nodes.filter(n=>n.status==='done').length,total=e.graph.nodes.length;return `<article class="hm-resume-card"><a href="#${url}" class="hm-resume-art">${art(p.art,p.name)}<span>${M.output(p)==='comic'?'漫画':M.output(p)==='motion'?'视频':'漫画 + 视频'}</span><b>继续创作 ↗</b></a><div><h3>${link(E(p.name),url,'')}</h3><p>${E(c.c.title)} <i>·</i> ${E(M.navigation?.task(c)||stages[e.stage]||'故事与章节')}</p><footer><small class="${failed?'error':stale?'warning':''}">${E(M.navigation?.status(c)||(failed?failed+' 个步骤待恢复':stale?stale+' 项来源已更新':done+'/'+total+' 步已就绪'))}</small>${link('项目详情',`/app/projects/${p.id}`,'hm-text-link')}</footer></div></article>`;}
  function projectList(query=''){const q=query.toLowerCase();return projectContexts().map(c=>{if(!q||c.p.name.toLowerCase().includes(q)||c.c.title.toLowerCase().includes(q))return c;const chapter=[...c.p.chapters,...(c.p.episodes||[])].find(ch=>ch.title.toLowerCase().includes(q));return chapter?M.context(c.p.id,chapter.id):null;}).filter(Boolean).slice(0,3).map(projectCard).join('')||`<div class="hm-home-empty"><span>✧</span><h3>${query?'没有找到这个故事':'下一个世界，从这里开始。'}</h3><p>${query?'试试项目名称或章节名称。':'写一句灵感，或先看看作品和创作配方。'}</p>${query?'':link('开始第一个故事 ↗','/app/new','hm-button secondary')}</div>`;}
  function taskGroups(){const groups={running:[],failed:[],stale:[],candidate:[]};for(const p of S.state.projects.filter(p=>!p.archived))for(const c of [...p.chapters,...(p.episodes||[])]){const e=M.ensure(p,c);for(const [k,pred]of Object.entries({running:n=>n.status==='running'||n.status==='queued'&&['running','paused'].includes(e.run?.status),failed:n=>n.status==='failed',stale:n=>n.status==='stale',candidate:n=>n.status==='done'&&n.version>n.adopted})){const nodes=k==='stale'&&M.adaptation?M.adaptation.sourceItems({p,c,e}):e.graph.nodes.filter(pred);if(nodes.length)groups[k].push({p,c,e,nodes});}}return groups;}
  function tasks(){const groups=taskGroups();return `<aside class="hm-tasks"><div class="hm-tasks-heading"><span>工作室动态</span>${link('全部 →','/app/tasks','hm-text-link')}</div>${[['running','◷','队列中','#b9a5ef'],['failed','↶','失败待恢复','#eea8b4'],['stale','◈','来源项（镜头/步骤）','#e8c18e'],['candidate','✦','候选待采用','#9ecab9']].map(([k,ic,t,color])=>action(`<span class="hm-task-icon" style="color:${color}">${ic}</span><span>${t}</span><b>${groups[k].reduce((n,g)=>n+g.nodes.length,0)}</b><i>↗</i>`,'tasks','hm-task-row',`data-kind="${k}"`)).join('')}<div class="hm-tasks-note"><i></i> 数量来自你的项目与章节<br><span>生成任务与费用均为本机模拟</span></div></aside>`;}
  function tools(){const list=ToolCatalog.home();return `<section class="hm-workspace-section">${label('创作工具','一个小想法，也能直接开始。','',link('全部工具 ↗','/app/tools','hm-text-link'))}<div class="hm-tool-grid">${list.map(tool=>link(`<div>${art(tool.art,tool.title)}<span>✧</span></div><h3>${tool.title}<b>↗</b></h3><p>${tool.desc}</p>`, '/app/tools/'+tool.id,'hm-tool-card')).join('')}</div></section>`;}

  const creationTypes={script:{name:'故事创作',title:'让一句灵感，长成一个好故事。',desc:'从一句灵感或已有原文开始，打磨人物与情节。',route:'/app/script?intent=new',cta:'开始新的故事',steps:'灵感与原文 / 故事与人物 / 分集与场次'},comic:{name:'漫画创作',title:'让故事里的世界，走进画格。',desc:'安排人物、分镜与对白，让故事走进画格。',route:'/app/comic',cta:'进入漫画创作',steps:'故事与资产 / 分场与脚本 / 漫画与排版'},video:{name:'视频创作',title:'把你的故事，做成动画。',desc:'从灵感开始，或使用已有故事、漫画。',route:'/app/new?source=idea&output=motion',cta:'开始新的动画',steps:'内容策划 / 视觉资产 / 镜头编排 / 生成与修改'}};
  let creationTab='video'; // 每次载入首页默认视频，不读取旧页签偏好。
  function recentCreation(){try{if(creationTab==='video'){const c=projectContexts().find(c=>M.output(c.p)==='motion');return c?link('继续最近视频：'+E(c.p.name),M.navigation?.resume(c)||path(c,c.e.stage,c.e.view),'hm-text-link'):'';}const raw=localStorage.getItem(creationTab==='script'?'cimora-script-studio-v1':'cimora-comic-studio-v1');if(!raw)return '';const db=JSON.parse(raw),p=db.projects?.find(p=>p.id===db.active)||db.projects?.at(-1);return p?link('继续最近'+(creationTab==='script'?'故事':'漫画')+'：'+E(p.title),'/app/'+creationTab+'?project='+encodeURIComponent(p.id),'hm-text-link'):'';}catch{return '';}}
  function creationPanel(){const x=creationTypes[creationTab];return `<div class="hm-create-copy"><span class="hm-eyebrow">YOUR STORY, YOUR WAY</span><h2>${x.title}</h2><p>${x.desc}</p><small>${x.steps}</small><div class="hm-create-actions">${link(x.cta+' →',x.route,'cm-button primary')}</div><div class="hm-create-recent">${recentCreation()}</div></div><div class="hm-create-art" aria-hidden="true"><img src="assets/cimora-cover.webp" alt=""></div>`;}
  function workspace(){return `<div class="hm-home hm-workspace"><section class="hm-create-hub" aria-label="创作入口"><div class="hm-create-heading"><span class="hm-eyebrow">我的创作宇宙</span><h1>把想象，变成你的作品。</h1><p>选一种表达，开始你的创作。</p></div><div class="hm-create-tabs" role="tablist" aria-label="创作类型">${['video','comic','script'].map(k=>{const x=creationTypes[k];return action(x.name,'creation-tab','',`role="tab" id="hm-type-${k}" data-type="${k}" aria-selected="${creationTab===k}" aria-controls="hm-create-panel"`);}).join('')}</div><div id="hm-create-panel" role="tabpanel" aria-labelledby="hm-type-${creationTab}">${creationPanel()}</div><div class="hm-create-secondary">${link('继续已有作品 ↗','/app/projects','hm-text-link')}${action('故事草稿箱','drafts','hm-text-link')}</div></section>${tools()}${worksSection(true)}${templatesSection(true)}<div class="hm-workspace-footer"><span>cimora</span> 为每一个想象中的世界，留一个位置。${link('访问官网 ↗','/','hm-text-link')}</div></div>`;}
  function showFilm(index){const f=films[index];S.modal(f.title+' · 作品画面',`<div class="hm-preview-modal"><img src="${f.cover}" alt="${f.title}"><span class="hm-eyebrow">${f.en}</span><h3>${f.line}</h3><p>${f.tag} · 原创概念素材。此处为静态画面预览，非实时生成视频。</p></div>`,(f.id?link('阅读示例作品 →','/app/community/'+f.id,'hm-button secondary'):'')+action('以这个灵感开始 ↗','use-film','hm-button primary',`data-film="${index}"`),true);}
  function launch(v){const result=M.startFromHome(v);if(result==='empty'){S.toast('先写一句故事，或点“换个灵感”。');return;}if(result==='draft-exists'){H.pending=v;const d=M.db.newDraft;S.modal('还有一份故事，等你继续',`<p class="hm-draft-intro">现有草稿会保留。你可以先继续它，也可以将它存入草稿箱，再开始新的灵感。</p><div class="hm-draft-summary"><strong>${E(d.name||'未命名故事')}</strong><p>${E((d.text||d.candidate||'').slice(0,180))}</p></div>`,action('继续原草稿','resume-draft','hm-button secondary')+action('备份旧稿，开始新灵感','replace-draft','hm-button primary'));return;}S.close();S.route('/app/new');}
  function drafts(){const current=M.db.newDraft,has=current&&(current.name||current.text||current.candidate),backups=M.db.draftBackups||[];S.modal('故事草稿箱',`<p class="hm-draft-intro">找回备份时，当前稿会自动备份。已创建的项目在“我的项目”中继续。</p>${has?`<div class="hm-draft-summary"><span class="hm-eyebrow">正在创作</span><strong>${E(current.name||'未命名故事')}</strong><p>${E((current.text||current.candidate||'').slice(0,150))}</p>${action('继续当前草稿 →','resume-draft','hm-button secondary')}</div>`:''}${backups.map((b,i)=>`<div class="hm-draft-summary"><span class="hm-eyebrow">${E(new Date(b.time).toLocaleString('zh-CN'))} · 自动备份</span><strong>${E(b.draft.name||'未命名故事')}</strong><p>${E((b.draft.text||b.draft.candidate||'').slice(0,150))}</p>${action('找回这份草稿 →','restore-draft','hm-button secondary',`data-index="${i}"`)}</div>`).join('')}${!has&&!backups.length?'<div class="hm-home-empty"><span>✧</span><h3>灵感还没落笔。</h3><p>写下一句故事，就能开始你的第一份草稿。</p></div>':''}`);}
  function repaintGallery(){S.$('#hm-slides').innerHTML=slides();S.$$('.hm-dot').forEach((b,i)=>b.setAttribute('aria-pressed',H.slide===i));S.$('#hm-film-announcement').textContent='0'+(H.slide+1)+' — '+films[H.slide].title;}
  document.addEventListener('click',ev=>{const el=ev.target.closest('[data-home]');if(!el)return;ev.preventDefault();switch(el.dataset.home){
    case'read-story':{S.modal('末班车录音 · 完整故事',`<article class="hm-story-reader"><p class="hm-eyebrow">原创示例 · 悬疑 / 友情</p>${ScriptSample.story.split(/\n\s*\n/).map(t=>'<p>'+E(t)+'</p>').join('')}<footer>— 全文完 —</footer></article>`,'',true);break;}
    case'creation-tab':{creationTab=el.dataset.type;S.$$('.hm-create-tabs button').forEach(b=>b.setAttribute('aria-selected',b.dataset.type===creationTab));const panel=S.$('#hm-create-panel');panel.setAttribute('aria-labelledby','hm-type-'+creationTab);panel.innerHTML=creationPanel();break;}
    case'previous':case'next':H.slide=(H.slide+(el.dataset.home==='next'?1:2))%3;repaintGallery();break;
    case'slide':H.slide=+el.dataset.index;repaintGallery();break;
    case'preview':showFilm(+el.dataset.film);break;
    case'use-film':{const scope=S.context.path==='/app'?'app':'public',d=inputState(scope);launch({text:films[+el.dataset.film].prompt,output:d.mode==='motion'?'motion':'comic',view:d.mode==='canvas'?'canvas':'flow'});break;}
    case'mode':{const f=el.closest('form'),d=inputState(f.dataset.scope);d.mode=el.dataset.mode;M.save();f.querySelectorAll('[data-home="mode"]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===d.mode));break;}
    case'sample':{const f=el.closest('form'),d=inputState(f.dataset.scope);d.sample=((d.sample??-1)+1)%films.length;d.text=films[d.sample].prompt;f.querySelector('textarea').value=d.text;M.save();break;}
    case'resume-draft':S.close();S.route('/app/new');break;
    case'drafts':drafts();break;
    case'restore-draft':if(M.restoreHomeDraft(+el.dataset.index)){S.toast('没有找到这份备份，请重新打开草稿箱。');break;}S.close();S.route('/app/new');S.toast('草稿已找回，原当前稿已自动备份。');break;
    case'replace-draft':M.startFromHome(H.pending,true);H.pending=null;S.close();S.route('/app/new');break;
    case'process':{H.step=+el.dataset.index;S.$$('.hm-process-steps article').forEach((a,i)=>{a.classList.toggle('active',i===H.step);a.querySelector('button').setAttribute('aria-expanded',i===H.step);a.querySelector('.hm-process-copy').hidden=i!==H.step;});S.$('#hm-process-preview').innerHTML=processPreview();break;}
    case'engineering':H.engineering=el.dataset.state;S.$('#hm-engine-preview').innerHTML=engineeringPreview();break;
    case'recover':if(H.engineering!=='failed'){S.toast('先选择“试试失败恢复”，查看独立示例。');break;}H.engineering='recovered';S.$('#hm-engine-preview').innerHTML=engineeringPreview();break;
    case'collection':H.collection=el.dataset.filter;S.$$('.hm-collection-filters button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===H.collection));S.$('#hm-collection').innerHTML=collection();break;
    case'template':{const x=C.catalog().find(t=>t.id===el.dataset.id);S.modal('创作配方 · '+x.title,`<div class="hm-template-modal">${art(x.art,x.title)}<p>${E(x.desc)}</p><ol>${x.steps.map(t=>`<li>${E(t)}</li>`).join('')}</ol><small>✦ ${x.price} 积分 · 模拟资源许可，后续模型费用另计。</small></div>`,link('查看许可与使用方式 →','/app/market/'+x.id,'hm-button primary'));break;}
    case'tasks':{const k=el.dataset.kind,title={running:'队列中的任务',failed:'失败待恢复',stale:'待处理来源项 · 镜头/步骤',candidate:'候选待采用'}[k],groups=taskGroups()[k];S.modal(title,groups.map(g=>`<div class="hm-task-detail"><div><strong>${E(g.p.name)} / ${E(g.c.title)}</strong><p>${g.nodes.filter(n=>!n.sourceDifference).map(n=>E(n.title)).join('、')}</p>${g.nodes.filter(n=>n.sourceDifference).map(n=>`<p>${link(E(n.title)+' · 比较 →',path(g,'boards','flow')+'&shot='+n.shotId+'&compare=1','hm-button secondary')}</p>`).join('')}</div>${g.nodes.some(n=>!n.sourceDifference)?link(k==='candidate'?'确认候选 →':'查看工程 →',k==='candidate'?path(g,'review','flow'):k==='stale'?path(g,g.e.stage,'canvas'):`/app/runs/${g.p.id}/${g.c.id}`,'hm-button secondary'):''}</div>`).join('')||'<div class="hm-home-empty"><span>✓</span><h3>这里暂时没有待处理事项。</h3><p>继续创作，工程状态会同步到这里。</p></div>');break;}
  }});
  document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.homeInput==='idea'){inputState(el.closest('form').dataset.scope).text=el.value;M.save();}if(el.dataset.homeInput==='project-search')S.$('#hm-home-projects').innerHTML=projectList(el.value.trim());});
  document.addEventListener('submit',ev=>{const f=ev.target.closest('[data-home-form="start"]');if(!f)return;ev.preventDefault();const d=inputState(f.dataset.scope);launch({text:f.querySelector('textarea').value,output:d.mode==='motion'?'motion':'comic',view:d.mode==='canvas'?'canvas':'flow'});});
  document.addEventListener('keydown',ev=>{if(!ev.target.closest('.hm-gallery')||!['ArrowLeft','ArrowRight'].includes(ev.key))return;ev.preventDefault();H.slide=(H.slide+(ev.key==='ArrowRight'?1:2))%3;repaintGallery();});
  C.pages.home=workspace;C.publicHome=official;C.home={projectList,taskGroups};
})();
